import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiStrengthen","description":"","frontmatter":{},"headers":[],"relativePath":"modules/strengthen/index.md","filePath":"modules/strengthen/index.md","lastUpdated":null}'),n={name:"modules/strengthen/index.md"};function i(o,t,s,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="emakistrengthen" tabindex="-1">EmakiStrengthen <a class="header-anchor" href="#emakistrengthen" aria-label="Permalink to &quot;EmakiStrengthen&quot;">​</a></h1><p>EmakiStrengthen 是装备强化模块，提供星级强化、锻印 temper、保护材料、里程碑、属性写入、强化层重建和公开 API。它适合制作&quot;装备从 +0 到 +N 逐步成长&quot;的玩法。</p><blockquote><p>部分命令仍使用 <code>crack</code> 等历史命名（如 <code>clearcrack</code>），在玩法描述中统一称为&quot;锻印&quot;或&quot;强化痕迹&quot;。</p></blockquote><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.6.4</code></td></tr><tr><td>主命令</td><td><code>/emakistrengthen</code></td></tr><tr><td>别名</td><td><code>/estrengthen</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiItem、EmakiAttribute、PlaceholderAPI</td></tr><tr><td>主要权限</td><td><code>emakistrengthen.use</code>、<code>emakistrengthen.reload</code>、<code>emakistrengthen.debug</code>、<code>emakistrengthen.admin</code></td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>打开强化 GUI、检查主手装备、刷新展示、设置星级与发放材料。</td></tr><tr><td><a href="./recipes.html">强化配方</a></td><td><code>recipes/*.yml</code> 的成功率、材料消耗、失败惩罚、效果与动作。</td></tr><tr><td><a href="./process.html">流程说明</a></td><td>从配方匹配到 PDC 写入与展示刷新的完整强化流程。</td></tr><tr><td><a href="./branch.html">分支树系统</a></td><td>按星级段划分的强化路线，以及不同路线给出的属性、技能与展示。</td></tr><tr><td><a href="./broadcast.html">广播系统</a></td><td>首次达到指定星级时向周围或全服发送通知。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>主手强化层的重建与修改动作。</td></tr><tr><td><a href="./api.html">API 接入</a></td><td>通过 <code>EmakiStrengthenApi</code> 读取状态、预览与执行强化。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>强化流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>强化星级</td><td>装备当前强化等级，例如 +1、+2、+10。</td></tr><tr><td>强化配方</td><td>定义哪些装备能强化、需要哪些材料、成功率和结果。</td></tr><tr><td>材料计划</td><td>判断并消耗强化材料、保护材料和锻印材料。</td></tr><tr><td>锻印（temper）</td><td>失败时累积的等级，按 <code>temper_chance_bonus_per_level</code> 提升后续成功率。</td></tr><tr><td>失败降星</td><td>目标星级 ≥ 6 且未使用保护材料时，失败会降 1 星。</td></tr><tr><td>保护材料</td><td><code>protection: true</code> 的材料，失败时阻止降星。</td></tr><tr><td>分支树</td><td>在指定星级后分叉为不同强化路线。</td></tr><tr><td>强化层</td><td>写入装备的 strengthen namespace layer，由 CoreLib 重建展示。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiStrengthen/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── example_recipe.yml</span></span>
<span class="line"><span>│   └── example_branch_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── strengthen_gui.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>recipes/</code> 决定不同装备的强化规则，<code>gui/strengthen_gui.yml</code> 决定强化界面布局。</p><h2 id="典型强化流程" tabindex="-1">典型强化流程 <a class="header-anchor" href="#典型强化流程" aria-label="Permalink to &quot;典型强化流程&quot;">​</a></h2><ol><li>玩家用 <code>/estrengthen open</code> 打开强化 GUI。</li><li>放入目标装备、强化材料和可选保护材料。</li><li>模块按配方的 <code>match</code> 规则匹配可用强化配方。</li><li>检查条件、材料、经济费用和当前星级上限。</li><li>计算成功率：目标星级基础成功率 + 锻印加成，并钳制到 <code>success_chance_cap</code>。</li><li>触发 <code>StrengthenPreAttemptEvent</code>，允许外部改写成功率或取消。</li><li>执行随机判定并扣除材料与费用。</li><li>成功时星级 +1，写入强化层，执行该星级的 <code>actions.success</code>。</li><li>失败时按规则累积锻印并可能降星，执行 <code>actions.failure</code>。</li><li>CoreLib 重建装备展示；首次达到广播星级时发送本地或全服广播。</li></ol><h2 id="与-attribute-的关系" tabindex="-1">与 Attribute 的关系 <a class="header-anchor" href="#与-attribute-的关系" aria-label="Permalink to &quot;与 Attribute 的关系&quot;">​</a></h2><p>Strengthen 可以仅作为展示和成长系统运行。配置 <code>ea_attribute</code> 效果并安装 EmakiAttribute 后，每个星级可以提供真实属性加成：属性通过 EmakiAttribute 的权威 API 写入结构化 PDC layer，参与真实战斗计算。</p><p>EmakiAttribute 未安装时走 no-op 路径，强化照常完成但不写入属性。</p><h2 id="与-item-的关系" tabindex="-1">与 Item 的关系 <a class="header-anchor" href="#与-item-的关系" aria-label="Permalink to &quot;与 Item 的关系&quot;">​</a></h2><p>安装 EmakiItem 时，Strengthen 会在其条件加载的 integration 包中通过 <code>EmakiItemApi</code> 注册物品层预览提供者，让 EmakiItem 侧能够预览强化层内容。EmakiItem 未安装或被禁用时该注册自动跳过或释放，不影响强化功能。</p>`,19)])])}const u=e(n,[["render",i]]);export{m as __pageData,u as default};
